<?php $d=admin_fields()[$resource];$table=$d['table'];$editing=isset($_GET['edit']);$record=$id?row("SELECT * FROM `$table` WHERE id=?".(!empty($d['type'])?' AND type=?':''),!empty($d['type'])?[$id,$d['type']]:[$id]):null; ?>
<?php if($editing): if($id&&!$record): ?><div class="alert alert-warning">Record not found.</div><?php else: ?>
<div class="admin-toolbar"><a class="tf-button style-3" href="<?= url('admin/manage.php?resource='.$resource) ?>">Back to list</a></div><div class="wg-box"><form method="post" enctype="multipart/form-data" class="admin-form"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= $id ?>"><div class="row"><?php foreach($d['fields'] as $k=>$kind): $value=$_POST[$k]??$record[$k]??(in_array($kind,['number','money'])?'0':($kind==='bool'?($k==='active'?1:0):''));$label=ucwords(str_replace('_',' ',$k)); ?>
<div class="<?= in_array($kind,['html','textarea','json'])?'col-12':'col-md-6' ?> field"><label for="<?= $k ?>"><?= h($label) ?></label>
<?php if(is_array($kind)): ?><select name="<?= $k ?>" id="<?= $k ?>"><?php foreach($kind as $choice): ?><option value="<?= h($choice) ?>" <?= $value===$choice?'selected':'' ?>><?= h(ucfirst($choice)) ?></option><?php endforeach; ?></select>
<?php elseif($kind==='bool'): ?><input id="<?= $k ?>" type="checkbox" name="<?= $k ?>" value="1" <?= $value?'checked':'' ?>>
<?php elseif($kind==='image'): ?><input type="file" id="<?= $k ?>" name="<?= $k ?>" accept="image/jpeg,image/png,image/webp,image/gif"><?php if(!empty($record[$k])): ?><img class="image-preview" src="<?= h(url($record[$k])) ?>" alt="Current image"><label><input type="checkbox" name="remove_<?= $k ?>"> Remove current image</label><?php endif; ?><p class="help">JPEG, PNG, WebP or GIF, maximum 10 MB.</p>
<?php elseif(in_array($kind,['html','textarea','json'])): ?><textarea id="<?= $k ?>" name="<?= $k ?>" class="<?= $kind==='html'?'rich-text':'' ?>" rows="<?= $kind==='html'?12:4 ?>"><?= h($value) ?></textarea><?php if($kind==='json'): ?><p class="help">Structured JSON; use [] when empty. Attributes example: {"Material":{"name":"Material","value":"Steel"}}</p><?php endif; ?>
<?php elseif(in_array($kind,['parent','blog_category'])): ?><select id="<?= $k ?>" name="<?= $k ?>"><option value="">None</option><?php foreach(rows('SELECT id,name FROM '.($kind==='parent'?'categories':'content_categories').' ORDER BY name') as $c): if($kind==='parent'&&$c['id']===$id)continue; ?><option value="<?= $c['id'] ?>" <?= $value==$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select>
<?php else: ?><input id="<?= $k ?>" name="<?= $k ?>" type="<?= in_array($kind,['money','optional_money','number'])?'number':($kind==='datetime'?'datetime-local':'text') ?>" <?= in_array($kind,['money','optional_money','number'])?'min="0" step="0.001"':'' ?> value="<?= h($kind==='datetime'&&$value?date('Y-m-d\TH:i',strtotime($value)):$value) ?>" <?= in_array($k,['name','title'])?'required maxlength="255"':'' ?>><?php endif; ?></div><?php endforeach; ?></div>
<?php if($resource==='products'): $selected=array_column(rows('SELECT category_id FROM product_categories WHERE product_id=?',[$id]),'category_id'); ?><label for="categories">Categories (hold Ctrl to select multiple)</label><select id="categories" name="categories[]" multiple><?php foreach(rows('SELECT * FROM categories ORDER BY name') as $c): ?><option value="<?= $c['id'] ?>" <?= in_array($c['id'],$_POST['categories']??$selected)?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select><label for="gallery">Add gallery images</label><input type="file" id="gallery" name="gallery[]" multiple accept="image/jpeg,image/png,image/webp,image/gif"><div class="row mt-3 mb-4"><?php foreach(rows('SELECT * FROM product_images WHERE product_id=? ORDER BY sort_order',[$id]) as $g): ?><div class="col-6 col-md-3"><img class="image-preview" src="<?= h(url($g['path'])) ?>" alt="Product gallery"><label><input type="checkbox" name="remove_gallery[]" value="<?= $g['id'] ?>"> Remove</label></div><?php endforeach; ?></div><label for="variants">Variants</label><p class="help">JSON list. Existing IDs update variants; removing a row deactivates it. Example: [{"sku":"SIZE-L","attributes":{"Size":"Large"},"price":1000,"stock":5,"manage_stock":1}]</p><textarea id="variants" name="variants" rows="8"><?= h($_POST['variants']??json_encode(rows('SELECT id,sku,attributes,price,regular_price,stock,manage_stock,stock_status,active FROM product_variants WHERE product_id=? AND active=1',[$id]),JSON_PRETTY_PRINT)) ?></textarea><?php endif; ?>
<button class="tf-button">Save changes</button></form></div><script src="<?= url('admin/js/tinymce/tinymce.min.js') ?>"></script><script>if(window.tinymce)tinymce.init({selector:'.rich-text',height:350,menubar:false,plugins:'lists link paste',toolbar:'undo redo | formatselect | bold italic | bullist numlist | link',promotion:false,branding:false});</script>
