<?php endif; else: $page=max(1,(int)($_GET['page']??1));$q=trim($_GET['q']??'');$field=isset($d['fields']['name'])?'name':'title';$where='1=1';$args=[];if(isset($d['type'])){$where.=' AND type=?';$args[]=$d['type'];}if($q!==''){$where.=" AND `$field` LIKE ?";$args[]='%'.$q.'%';}$total=(int)scalar("SELECT COUNT(*) FROM `$table` WHERE $where",$args);$list=rows("SELECT * FROM `$table` WHERE $where ORDER BY id DESC LIMIT 25 OFFSET ".(($page-1)*25),$args); ?>
<div class="admin-toolbar"><a class="tf-button" href="<?= url('admin/manage.php?resource='.$resource.'&edit=1') ?>">Add new</a><form method="get"><input type="hidden" name="resource" value="<?= h($resource) ?>"><input name="q" placeholder="Search…" value="<?= h($q) ?>"><button class="tf-button style-3">Search</button></form><span><?= $total ?> records</span></div><div class="wg-box"><div class="table-scroll"><table class="admin-table"><thead><tr><th>ID</th><th><?= ucfirst($field) ?></th><?php if($resource==='products'): ?><th>Price</th><th>Stock</th><?php endif; ?><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($list as $r): ?><tr><td><?= $r['id'] ?></td><td><?php if(!empty($r['image'])): ?><img width="48" height="48" style="object-fit:contain" src="<?= h(url($r['image'])) ?>" alt=""><?php endif; ?> <a href="<?= url('admin/manage.php?resource='.$resource.'&id='.$r['id'].'&edit=1') ?>"><?= h($r[$field]) ?></a></td><?php if($resource==='products'): ?><td><?= h(money($r['price'])) ?></td><td><?= $r['manage_stock']?h((float)$r['stock']):h($r['stock_status']) ?></td><?php endif; ?><td><?= h($r['status']??($r['active']??1?'Active':'Inactive')) ?></td><td><a href="<?= url('admin/manage.php?resource='.$resource.'&id='.$r['id'].'&edit=1') ?>">Edit</a><form method="post" data-confirm="Archive or safely remove this record?"><?= csrf_field() ?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn">Archive / remove</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><div class="admin-toolbar mt-4"><?php if($page>1): ?><a class="tf-button style-3" href="?<?= h(http_build_query(array_merge($_GET,['page'=>$page-1]))) ?>">Previous</a><?php endif; ?>Page <?= $page ?> of <?= max(1,ceil($total/25)) ?><?php if($page*25<$total): ?><a class="tf-button style-3" href="?<?= h(http_build_query(array_merge($_GET,['page'=>$page+1]))) ?>">Next</a><?php endif; ?></div><?php endif; ?>
